import { v4 as uuidv4 } from "uuid";
import { useRef } from "react";
import useTooltip from "./hooks/useTooltip";

const Menu = ({ items }) => {
    const imgRef = useRef(null);
    const {
        tooltip,
        pos,
        showTooltip,
        moveTooltip,
        hideTooltip
    } = useTooltip();
    return (
        <section className="Menu text-body">
            <div className="Menu__track-wrapper">
                <ul className="Menu__track">
                    {items.map((element) => (
                        <li key={uuidv4()}>
                            <a href={element.link} target="_blank" rel="noopener noreferrer">
                                {element.title}
                            </a>
                        </li>
                    ))}
                </ul>
                <ul className="Menu__track" aria-hidden="true">
                    {items.map((element) => (
                        <li key={uuidv4()}>
                            <a href=
                                {element.link} 
                                target="_blank" 
                                rel="noopener 
                                noreferrer"
                                                        onMouseEnter={(e) =>
                            showTooltip(
                                e,
                                imgRef,
                                "Download CV"
                            )
                        }
                        onMouseMove={moveTooltip}
                        onMouseLeave={hideTooltip}
                        >
                                {element.title}
                            </a>
                        </li>
                    ))}
                </ul>
            </div>
            {tooltip && (
                <div
                    className="projects__tooltip"
                    style={{
                        backgroundColor: tooltip.bg,
                        color: tooltip.color,
                        top: pos.y + 16,
                        left: pos.x + 16,
                    }}
                >
                    {tooltip.text}
                </div>
            )}
        </section>
    );
};

export default Menu;
